// Fictional browser fixture: intercept all application requests; no external transport.
import React from 'react';import{createRoot}from'react-dom/client';import{BrowserRouter}from'react-router';import App from '../../../src/App';import '../../../src/CSS/main.css';
const params=new URLSearchParams(location.search),mode=params.get('mode')??'admin',delay=Number(params.get('delay')??600);let calls=[],shift=0,positions=[],running=false;const user=()=>localStorage.getItem('fixture-user')??'a';
window.fetch=async(input)=>{const path=String(input),who=user();calls.push({path,at:performance.now()});await new Promise(r=>setTimeout(r,delay));if(path==='/api/auth/session')return who==='signed-out'?Response.json({},{status:401}):Response.json({account:{userId:who,nickname:'Fictional '+who,memberNumber:'1'},csrfToken:(who==='a'?'a':'b').repeat(64),emailVerified:true});if(path==='/api/manage/capabilities')return mode==='error'?Response.json({},{status:503}):Response.json({sections:mode==='ordinary'?[]:mode==='staff'?['events']:['users','roles','events']});if(path==='/api/auth/logout'){localStorage.setItem('fixture-user','signed-out');return Response.json({});}throw Error('External request forbidden');};
new PerformanceObserver(list=>{for(const e of list.getEntries())shift+=e.value}).observe({type:'layout-shift',buffered:true});
const controls=document.createElement('div');controls.style='position:fixed;bottom:0;right:0;z-index:999;background:white;color:black;font:10px monospace;max-width:100%';controls.innerHTML='<button id="measure">Measure</button><button id="switch">Switch account</button><button id="signout">Other tab logout</button><output id="metrics"></output>';document.body.append(controls);
function record(){if(running){const filter=document.querySelector('.events-filters'),nav=[...document.querySelectorAll('.site-nav a')].find(x=>x.textContent==='Administration');positions.push({filter:filter?.getBoundingClientRect().top,nav:nav?.getBoundingClientRect().left});}requestAnimationFrame(record)}requestAnimationFrame(record);
document.querySelector('#measure').onclick=()=>{calls=[];shift=0;positions=[];running=true;};document.querySelector('#switch').onclick=()=>{localStorage.setItem('fixture-user',user()==='a'?'b':'a');new BroadcastChannel('lan-auth-invalidation').postMessage('invalidate')};document.querySelector('#signout').onclick=()=>{localStorage.setItem('fixture-user','signed-out');new BroadcastChannel('lan-auth-invalidation').postMessage('invalidate')};
setInterval(()=>{const y=positions.map(p=>p.filter).filter(Number.isFinite),x=positions.map(p=>p.nav).filter(Number.isFinite);document.querySelector('#metrics').textContent=JSON.stringify({calls:calls.map(c=>c.path),shift,filterDelta:y.length?Math.max(...y)-Math.min(...y):0,navDelta:x.length?Math.max(...x)-Math.min(...x):0,navMissing:positions.filter(p=>p.nav===undefined).length,overflow:document.documentElement.scrollWidth>innerWidth});},50);
if(location.pathname.endsWith('.html'))history.replaceState(null,'',params.get('route')??'/');createRoot(document.getElementById('root')).render(<BrowserRouter><App/></BrowserRouter>);